/** The AM and PM markers Android uses for a locale: its own, else its language's, else AM and PM. */
internal fun androidAmPm(language: String, script: String?, region: String?): List<String> {
    val tag = listOfNotNull(language, script?.ifEmpty { null }, region?.ifEmpty { null }).joinToString("-")
    return (ANDROID_AM_PM[tag] ?: ANDROID_AM_PM[language] ?: "AM|PM").split("|")
}
